// =============================================================================
// Add delegates: one at a time, or from a CSV upload with a preview and an
// import report. Membership IDs and QR signatures are generated by the server;
// this page never sends either.
// =============================================================================
import {
  $, MANAGER_ROLES, AUTH_EVENT, getSession, clearSession, api, el, fmtInt, toast,
} from './common.js';

// Same limits and header as the server (internal/domain/ingest.go).
const MAX_BYTES = 5 * 1024 * 1024;
const MAX_ROWS = 10000;
const COLUMNS = ['full_name', 'email', 'team_name', 'date_of_birth', 'venue_id'];
const PREVIEW_ROWS = 200;
const REPORT_ROWS = 1000; // per table; the downloaded results have every row

const state = {
  venues: [],
  file: null,       // File chosen for upload
  parsed: null,     // { header, rows: [{ line, cells }] }
  result: null,     // ImportResult from the server
  uploading: false,
  templateURL: '',
};

// -----------------------------------------------------------------------------
// Shared helpers
// -----------------------------------------------------------------------------

const cleanMessage = (msg) => String(msg || '').replace(/^validation failed: /, '');

/** Normalizes a header cell like the server: "Full Name" -> "full_name". */
const normalizeHeader = (h) => h.replace(/^\uFEFF/, '').trim().toLowerCase().split(/\s+/).join('_');

const EMAIL_RE = /^[^\s@<>()",;:]+@[^\s@<>()",;:]+\.[^\s@<>()",;:]+$/;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function passURL(membershipId, email) {
  const q = new URLSearchParams({ id: membershipId, email });
  return `${location.origin}/pass.html?${q}`;
}

function venueLabel(v) {
  return v.hall_section ? `${v.name} · ${v.hall_section}` : v.name;
}

async function copyText(text, what) {
  try {
    await navigator.clipboard.writeText(text);
    toast(`${what} copied.`);
  } catch {
    toast(`Couldn’t copy. Select it and copy by hand: ${text}`, 'warn');
  }
}

/**
 * One CSV cell. Values that a spreadsheet would run as a formula get a
 * leading apostrophe, since names and emails in the report are user input.
 */
function csvCell(v) {
  let s = v == null ? '' : String(v);
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

const csvLine = (cells) => cells.map(csvCell).join(',');

function download(name, text) {
  // The BOM makes Excel read the file as UTF-8 (names with accents).
  const url = URL.createObjectURL(new Blob(['\uFEFF', text], { type: 'text/csv;charset=utf-8' }));
  const a = el('a', { href: url, download: name });
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** Ends the session the same way common.js does when the API says so. */
function sessionEnded(message) {
  clearSession();
  window.dispatchEvent(new CustomEvent(AUTH_EVENT, { detail: { message } }));
}

// -----------------------------------------------------------------------------
// Venues and the sample template
// -----------------------------------------------------------------------------

async function loadVenues() {
  try {
    state.venues = await api('/api/v1/admin/venues');
  } catch (err) {
    if (err.status === 401) return;
    toast(`Couldn’t load venues: ${err.message}`, 'warn');
    state.venues = [];
  }
  renderVenues();
  buildTemplate();
}

function renderVenues() {
  const select = $('p-venue');
  select.replaceChildren(
    el('option', { value: '' }, 'Unassigned'),
    ...state.venues.map((v) => el('option', { value: v.id }, venueLabel(v))),
  );

  $('venue-rows').replaceChildren(...state.venues.map((v) => el('tr', {},
    el('td', { class: 'td' }, venueLabel(v)),
    el('td', { class: 'td font-mono text-xs' }, v.id),
    el('td', { class: 'td text-right' },
      el('button', {
        type: 'button', class: 'font-bold text-action hover:underline',
        'aria-label': `Copy the venue_id of ${venueLabel(v)}`,
        onclick: () => copyText(v.id, 'Venue ID'),
      }, 'Copy')),
  )));
  $('venue-empty').hidden = state.venues.length > 0;
}

/** The template is built here so its example rows use a real venue ID. */
function buildTemplate() {
  const venue = state.venues[0]?.id || '';
  const text = [
    csvLine(COLUMNS),
    csvLine(['Ada Reyes', 'ada.reyes@example.com', 'Orion Developers', '1998-04-12', venue]),
    csvLine(['Lin Tan', 'lin.tan@example.com', 'Orion Developers', '2010-09-30', venue]),
    csvLine(['Kwame Mensah', 'k.mensah@example.com', '', '', '']),
  ].join('\r\n') + '\r\n';
  if (state.templateURL) URL.revokeObjectURL(state.templateURL);
  state.templateURL = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' }));
  $('template-link').href = state.templateURL;
}

// -----------------------------------------------------------------------------
// Tabs
// -----------------------------------------------------------------------------

const TABS = ['single', 'csv'];

function selectTab(name, focus = false) {
  for (const t of TABS) {
    const on = t === name;
    const tab = $(`tab-${t}`);
    tab.setAttribute('aria-selected', String(on));
    tab.tabIndex = on ? 0 : -1;
    $(`panel-${t}`).hidden = !on;
    if (on && focus) tab.focus();
  }
  try { sessionStorage.setItem('nsac_ingest_tab', name); } catch { /* private mode */ }
}

function onTabKey(e) {
  const i = TABS.findIndex((t) => $(`tab-${t}`) === document.activeElement);
  if (i < 0) return;
  let next = null;
  if (e.key === 'ArrowRight') next = TABS[(i + 1) % TABS.length];
  if (e.key === 'ArrowLeft') next = TABS[(i - 1 + TABS.length) % TABS.length];
  if (e.key === 'Home') next = TABS[0];
  if (e.key === 'End') next = TABS[TABS.length - 1];
  if (next) {
    e.preventDefault();
    selectTab(next, true);
  }
}

// -----------------------------------------------------------------------------
// Tab 1: single entry
// -----------------------------------------------------------------------------

function singleError(msg) {
  $('single-error').textContent = msg;
  $('single-error').hidden = !msg;
}

function showIngestOff(message) {
  $('ingest-off').textContent = `${message} Ask whoever runs the server to set it, then reload.`;
  $('ingest-off').hidden = false;
}

async function submitSingle(e) {
  e.preventDefault();
  singleError('');
  const body = {
    full_name: $('p-name').value.trim(),
    email: $('p-email').value.trim(),
    team_name: $('p-team').value.trim(),
    date_of_birth: $('p-dob').value,
    venue_id: $('p-venue').value,
  };
  if (!body.full_name) {
    singleError('Enter the delegate’s full name.');
    $('p-name').focus();
    return;
  }
  if (!body.email || !$('p-email').checkValidity()) {
    singleError('Enter a valid email address.');
    $('p-email').focus();
    return;
  }
  if (body.date_of_birth && !$('p-dob').checkValidity()) {
    singleError('That date of birth is out of range.');
    $('p-dob').focus();
    return;
  }

  const btn = $('single-submit');
  btn.disabled = true;
  btn.textContent = 'Adding…';
  try {
    const p = await api('/api/v1/admin/participants/create', { method: 'POST', body });
    showSingleResult(p);
    $('single-form').reset();
    $('p-name').focus();
  } catch (err) {
    if (err.status === 401) return;
    if (err.status === 503) showIngestOff(err.message);
    singleError(cleanMessage(err.message));
  } finally {
    btn.disabled = false;
    btn.textContent = 'Add delegate';
  }
}

function showSingleResult(p) {
  $('sr-id').textContent = p.membership_id;
  $('sr-name').textContent = p.full_name;
  $('sr-email').textContent = p.email;
  $('sr-pass').href = passURL(p.membership_id, p.email);
  $('sr-copy').onclick = () => copyText(passURL(p.membership_id, p.email), 'Pass link');
  $('single-result').hidden = false;

  $('session-rows').prepend(el('tr', {},
    el('td', { class: 'td whitespace-nowrap font-bold tabular-nums' }, p.membership_id),
    el('td', { class: 'td' }, p.full_name),
    el('td', { class: 'td' }, p.email),
    el('td', { class: 'td text-ink-soft' }, p.team_name || '—'),
  ));
  $('session-wrap').hidden = false;
  toast(`${p.full_name} added as ${p.membership_id}.`);
}

// -----------------------------------------------------------------------------
// Tab 2: CSV, step 1 (choose) and 2 (preview)
// -----------------------------------------------------------------------------

/**
 * RFC 4180 parser with the same rules as Go's encoding/csv on the server, so
 * a file that previews cleanly isn't then rejected: a quote may only open a
 * field or be doubled inside a quoted one, and only \n or \r\n end a record.
 * Each record carries the line it starts on, numbered as the server does.
 */
function parseCSV(text) {
  const records = [];
  let row = [];
  let cell = '';
  let quoted = false;
  let line = 1;
  let rowLine = 1;
  let i = 0;
  const endCell = () => { row.push(cell); cell = ''; };
  const stray = () => new Error(
    `Line ${line} has a quote (") inside a field. Put the whole field in quotes and double the inner ones ("").`);

  while (i < text.length) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { cell += '"'; i += 2; continue; }
      if (c === '"') {
        quoted = false;
        i++;
        const n = text[i];
        if (n !== undefined && n !== ',' && n !== '\n' && !(n === '\r' && text[i + 1] === '\n')) throw stray();
        continue;
      }
      if (c === '\n') line++;
      cell += c;
      i++;
      continue;
    }
    if (c === '"') {
      if (cell !== '') throw stray();
      quoted = true;
      i++;
      continue;
    }
    if (c === ',') { endCell(); i++; continue; }
    if (c === '\n' || (c === '\r' && text[i + 1] === '\n')) {
      i += c === '\r' ? 2 : 1;
      line++;
      // An empty line is not a record (the server skips them too).
      if (row.length > 0 || cell !== '') {
        endCell();
        records.push({ line: rowLine, cells: row });
        row = [];
      }
      rowLine = line;
      continue;
    }
    cell += c;
    i++;
  }
  if (quoted) throw new Error(`Line ${rowLine} has a quote that is never closed.`);
  if (row.length > 0 || cell !== '') {
    endCell();
    records.push({ line: rowLine, cells: row });
  }
  return records;
}

function csvError(msg) {
  $('csv-error').textContent = msg;
  $('csv-error').hidden = !msg;
}

function showStep(step) {
  $('dropzone').hidden = step !== 'choose';
  $('preview').hidden = step !== 'preview';
  $('progress').hidden = step !== 'progress';
  $('report').hidden = step !== 'report';
}

async function handleFile(file) {
  csvError('');
  if (!file) return;
  if (!/\.csv$/i.test(file.name) && file.type !== 'text/csv') {
    csvError(`“${file.name}” isn’t a CSV file. In Excel or Google Sheets, use File → Download / Save as → CSV.`);
    return;
  }
  if (file.size > MAX_BYTES) {
    csvError(`“${file.name}” is ${(file.size / 1048576).toFixed(1)} MB; the limit is 5 MB. Split it into smaller files.`);
    return;
  }

  let records;
  try {
    records = parseCSV(await file.text());
  } catch (err) {
    csvError(`Couldn’t read “${file.name}”: ${err.message}`);
    return;
  }
  if (records.length === 0) {
    csvError(`“${file.name}” is empty.`);
    return;
  }

  const header = records[0].cells.map(normalizeHeader);
  if (header.includes('membership_id')) {
    csvError('Remove the membership_id column: IDs are assigned automatically.');
    return;
  }
  const missing = ['full_name', 'email'].filter((c) => !header.includes(c));
  if (missing.length) {
    csvError(`The first row must be the header, including ${missing.join(' and ')}. Expected: ${COLUMNS.join(',')}`);
    return;
  }
  const rows = records.slice(1).filter((r) => r.cells.some((c) => c.trim() !== ''));
  if (rows.length === 0) {
    csvError(`“${file.name}” has a header but no delegates.`);
    return;
  }
  if (rows.length > MAX_ROWS) {
    csvError(`“${file.name}” has ${fmtInt(rows.length)} delegates; the limit is ${fmtInt(MAX_ROWS)} per file. Split it.`);
    return;
  }

  state.file = file;
  state.parsed = { header, rows };
  renderPreview();
  showStep('preview');
}

/** Problems the browser can spot. The server checks again, plus existing emails. */
function rowProblem(get, seen) {
  const email = get('email').trim().toLowerCase();
  if (!get('full_name').trim()) return 'Full name missing';
  if (!email) return 'Email missing';
  if (!EMAIL_RE.test(email)) return 'Email looks invalid';
  if (seen.has(email)) return `Repeats line ${seen.get(email)}`;
  const dob = get('date_of_birth').trim();
  if (dob && (!DATE_RE.test(dob) || Number.isNaN(Date.parse(dob)))) return 'Date not YYYY-MM-DD';
  if (dob && (dob < '1900-01-01' || dob > todayISO())) return 'Date of birth out of range';
  const venue = get('venue_id').trim();
  if (venue && !UUID_RE.test(venue)) return 'venue_id is not an ID';
  if (venue && state.venues.length && !state.venues.some((v) => v.id === venue.toLowerCase())) return 'Unknown venue_id';
  return '';
}

function renderPreview() {
  const { header, rows } = state.parsed;
  const index = Object.fromEntries(header.map((h, i) => [h, i]));
  const shown = COLUMNS.filter((c) => c in index);
  const ignored = header.filter((h) => h && !COLUMNS.includes(h));

  const seen = new Map();
  let flagged = 0;
  const checked = rows.map((r) => {
    const get = (name) => (name in index ? r.cells[index[name]] ?? '' : '');
    const problem = rowProblem(get, seen);
    const email = get('email').trim().toLowerCase();
    if (email && !seen.has(email)) seen.set(email, r.line);
    if (problem) flagged++;
    return { line: r.line, get, problem };
  });

  $('pv-file').textContent = state.file.name;
  $('pv-summary').textContent =
    `${fmtInt(rows.length)} delegate${rows.length === 1 ? '' : 's'} found · ` +
    (flagged ? `${fmtInt(flagged)} with problems (skipped and listed in the report)` : 'no problems spotted') +
    ' · Already-registered emails are checked when you import.';

  const warnings = [];
  if (ignored.length) warnings.push(`Ignored column${ignored.length === 1 ? '' : 's'}: ${ignored.join(', ')}.`);
  const absent = COLUMNS.filter((c) => !(c in index) && c !== 'full_name' && c !== 'email');
  if (absent.length) warnings.push(`No ${absent.join(', ')} column; those stay blank.`);
  $('pv-warning').textContent = warnings.join(' ');
  $('pv-warning').hidden = warnings.length === 0;

  const venueName = Object.fromEntries(state.venues.map((v) => [v.id, venueLabel(v)]));
  $('pv-head').replaceChildren(
    el('th', { class: 'th', scope: 'col' }, 'Line'),
    ...shown.map((c) => el('th', { class: 'th', scope: 'col' }, c)),
    el('th', { class: 'th', scope: 'col' }, 'Check'),
  );
  $('pv-rows').replaceChildren(...checked.slice(0, PREVIEW_ROWS).map((r) => el('tr', { class: r.problem ? 'bg-stop/5' : '' },
    el('td', { class: 'td tabular-nums text-ink-soft' }, String(r.line)),
    ...shown.map((c) => {
      const v = r.get(c).trim();
      const label = c === 'venue_id' && venueName[v.toLowerCase()] ? venueName[v.toLowerCase()] : v;
      return el('td', { class: 'td max-w-[240px] truncate', title: v }, label || '—');
    }),
    el('td', { class: 'td whitespace-nowrap' }, r.problem
      ? el('span', { class: 'pill bg-stop/10 text-stop' }, r.problem)
      : el('span', { class: 'pill bg-go/10 text-go' }, 'OK')),
  )));
  $('pv-more').textContent = `Showing the first ${fmtInt(PREVIEW_ROWS)} of ${fmtInt(rows.length)} rows.`;
  $('pv-more').hidden = rows.length <= PREVIEW_ROWS;
  $('pv-import').textContent = `Import ${fmtInt(rows.length)} delegate${rows.length === 1 ? '' : 's'}`;
}

function resetUpload() {
  state.file = null;
  state.parsed = null;
  state.result = null;
  $('csv-input').value = '';
  csvError('');
  showStep('choose');
}

// -----------------------------------------------------------------------------
// Tab 2: step 3 (upload with progress) and 4 (report)
// -----------------------------------------------------------------------------

function setProgress(label, pct) {
  $('pg-label').textContent = label;
  if (pct == null) {
    // Server-side work: no measurable progress, so pulse a full bar.
    $('pg-fill').style.width = '100%';
    $('pg-fill').classList.add('animate-pulse');
    $('pg-pct').textContent = '';
    $('pg-bar').removeAttribute('aria-valuenow');
  } else {
    $('pg-fill').classList.remove('animate-pulse');
    $('pg-fill').style.width = `${pct}%`;
    $('pg-pct').textContent = `${pct}%`;
    $('pg-bar').setAttribute('aria-valuenow', String(pct));
  }
}

/** XMLHttpRequest rather than fetch: only XHR reports upload progress. */
function uploadCSV(file) {
  return new Promise((resolve, reject) => {
    const token = getSession()?.token;
    if (!token) {
      sessionEnded('Your session ended. Sign in again.');
      reject(Object.assign(new Error('Not signed in'), { status: 401 }));
      return;
    }
    const xhr = new XMLHttpRequest();
    xhr.open('POST', '/api/v1/admin/participants/upload-csv');
    xhr.setRequestHeader('Authorization', `Bearer ${token}`);
    xhr.responseType = 'json';
    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable) setProgress('Uploading…', Math.min(99, Math.round((e.loaded / e.total) * 100)));
    };
    xhr.upload.onload = () => setProgress(`Checking and adding ${fmtInt(state.parsed.rows.length)} delegates…`, null);
    xhr.onerror = () => reject(Object.assign(new Error('The upload failed. Check the connection and try again.'), { status: 0 }));
    xhr.ontimeout = () => reject(Object.assign(new Error('The server took too long to answer.'), { status: 0 }));
    xhr.onload = () => {
      const body = xhr.response;
      if (xhr.status === 401) {
        sessionEnded('Your session ended. Sign in again.');
      } else if (xhr.status === 403 && body?.code === 'PASSWORD_CHANGE_REQUIRED') {
        sessionEnded('Your password was reset. Sign in with the temporary password from your email.');
      }
      if (xhr.status >= 200 && xhr.status < 300) resolve(body);
      else reject(Object.assign(new Error(body?.error || `Upload failed (HTTP ${xhr.status})`), { status: xhr.status }));
    };
    const form = new FormData();
    form.append('file', file, file.name);
    xhr.send(form);
  });
}

async function startImport() {
  if (!state.file || state.uploading) return;
  state.uploading = true;
  csvError('');
  showStep('progress');
  setProgress('Uploading…', 0);
  try {
    state.result = await uploadCSV(state.file);
    renderReport();
    showStep('report');
    $('report').focus();
  } catch (err) {
    if (err.status === 401 || err.status === 403) return;
    if (err.status === 503) showIngestOff(err.message);
    csvError(cleanMessage(err.message));
    showStep('preview');
  } finally {
    state.uploading = false;
  }
}

function issueRows(list) {
  return list.slice(0, REPORT_ROWS).map((d) => el('tr', {},
    el('td', { class: 'td tabular-nums text-ink-soft' }, String(d.line)),
    el('td', { class: 'td' }, d.email || '—'),
    el('td', { class: 'td' }, d.message),
  ));
}

function renderReport() {
  const r = state.result;
  $('rp-created').textContent = fmtInt(r.created.length);
  $('rp-dups').textContent = fmtInt(r.duplicates.length);
  $('rp-errors').textContent = fmtInt(r.errors.length);

  $('rp-error-rows').replaceChildren(...issueRows(r.errors));
  $('rp-dup-rows').replaceChildren(...issueRows(r.duplicates));
  $('rp-created-rows').replaceChildren(...r.created.slice(0, REPORT_ROWS).map((c) => el('tr', {},
    el('td', { class: 'td tabular-nums text-ink-soft' }, String(c.line)),
    el('td', { class: 'td whitespace-nowrap font-bold tabular-nums' }, c.membership_id),
    el('td', { class: 'td' }, c.full_name),
    el('td', { class: 'td' }, c.email),
  )));

  const more = (n) => (n > REPORT_ROWS ? ` (first ${fmtInt(REPORT_ROWS)} shown; download for all)` : '');
  $('rp-errors-box').querySelector('summary').textContent = `Row error log: ${fmtInt(r.errors.length)}${more(r.errors.length)}`;
  $('rp-dups-box').querySelector('summary').textContent = `Duplicates skipped: ${fmtInt(r.duplicates.length)}${more(r.duplicates.length)}`;
  $('rp-created-box').querySelector('summary').textContent = `Delegates added: ${fmtInt(r.created.length)}${more(r.created.length)}`;
  $('rp-errors-box').hidden = r.errors.length === 0;
  $('rp-dups-box').hidden = r.duplicates.length === 0;
  $('rp-created-box').hidden = r.created.length === 0;
  $('rp-created-box').open = r.errors.length === 0;

  const tone = r.errors.length ? 'warn' : 'ok';
  toast(`Import finished: ${fmtInt(r.created.length)} added, ${fmtInt(r.duplicates.length)} duplicates, ${fmtInt(r.errors.length)} errors.`, tone);
}

/** Every row of the file with its outcome, in file order. */
function downloadResults() {
  const r = state.result;
  if (!r) return;
  const rows = [
    ...r.created.map((c) => ({ line: c.line, status: 'added', id: c.membership_id, name: c.full_name, email: c.email, msg: '', link: passURL(c.membership_id, c.email) })),
    ...r.duplicates.map((d) => ({ line: d.line, status: 'duplicate', id: '', name: '', email: d.email, msg: d.message, link: '' })),
    ...r.errors.map((e) => ({ line: e.line, status: 'error', id: '', name: '', email: e.email, msg: e.message, link: '' })),
  ].sort((a, b) => a.line - b.line);
  const text = [
    csvLine(['line', 'status', 'membership_id', 'full_name', 'email', 'message', 'pass_link']),
    ...rows.map((x) => csvLine([x.line, x.status, x.id, x.name, x.email, x.msg, x.link])),
  ].join('\r\n') + '\r\n';
  const base = (state.file?.name || 'delegates.csv').replace(/\.csv$/i, '');
  download(`${base}-import-results.csv`, text);
}

// -----------------------------------------------------------------------------
// Boot
// -----------------------------------------------------------------------------

function toSignIn(message) {
  // Sign-in (including the first-password step) lives on the dashboard page.
  if (message) sessionStorage.setItem('nsac_signin_message', message);
  location.replace('/admin/dashboard.html');
}

function wireDropzone() {
  const zone = $('dropzone');
  const input = $('csv-input');
  zone.addEventListener('click', () => input.click());
  zone.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      input.click();
    }
  });
  input.addEventListener('change', () => handleFile(input.files[0]));

  let depth = 0; // dragenter/leave fire for every child element
  zone.addEventListener('dragenter', (e) => { e.preventDefault(); depth++; zone.classList.add('is-over'); });
  zone.addEventListener('dragover', (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
  zone.addEventListener('dragleave', () => { if (--depth <= 0) { depth = 0; zone.classList.remove('is-over'); } });
  zone.addEventListener('drop', (e) => {
    e.preventDefault();
    depth = 0;
    zone.classList.remove('is-over');
    const files = e.dataTransfer.files;
    if (files.length > 1) toast('Only the first file is used. Upload the others one at a time.', 'warn');
    handleFile(files[0]);
  });
  // A file dropped beside the zone would otherwise open in the tab and lose the page.
  window.addEventListener('dragover', (e) => e.preventDefault());
  window.addEventListener('drop', (e) => e.preventDefault());
}

function boot() {
  const session = getSession();
  if (!session) return toSignIn();
  if (!MANAGER_ROLES.includes(session.role)) {
    clearSession();
    return toSignIn('Scanner accounts can’t open the control panel.');
  }

  $('signed-in-as').textContent = session.full_name;
  $('app').hidden = false;

  window.addEventListener(AUTH_EVENT, (e) => toSignIn(e.detail?.message));
  $('logout').addEventListener('click', () => { clearSession(); toSignIn(); });
  window.addEventListener('beforeunload', (e) => {
    if (state.uploading) e.preventDefault();
  });

  for (const t of TABS) $(`tab-${t}`).addEventListener('click', () => selectTab(t));
  document.querySelector('[role=tablist]').addEventListener('keydown', onTabKey);
  let saved = 'single';
  try { saved = sessionStorage.getItem('nsac_ingest_tab') || 'single'; } catch { /* private mode */ }
  selectTab(TABS.includes(saved) ? saved : 'single');

  $('p-dob').max = todayISO();
  $('single-form').addEventListener('submit', submitSingle);
  $('single-form').addEventListener('reset', () => singleError(''));

  wireDropzone();
  $('pv-cancel').addEventListener('click', resetUpload);
  $('pv-import').addEventListener('click', startImport);
  $('rp-again').addEventListener('click', resetUpload);
  $('rp-download').addEventListener('click', downloadResults);

  buildTemplate(); // usable before venues load; rebuilt with a real venue ID after
  loadVenues();
}

boot();
